resources.string:
{count, plural,
        =1      {دەبێت پین لانی کەم خاوەنی # ژمارە بێت، بەڵام پینێکی {minAutoConfirmLen} ژمارەیی پێشنیار دەکرێت بۆ ئاسایشی زیاتر}
        other   {دەبێت پین لانی کەم # ژمارە بێت، بەڵام پینێکی {minAutoConfirmLen} ژمارەیی پێشنیار دەکرێت بۆ ئاسایشی زیاتر}
        }

{count, plural, offset:2
=0    {دۆخەکان دەتوانن دۆخی تاریکیش چالاک بکەن}
=1    {{mode_1}یش دۆخی تاریک چالاک دەکات}
=2    {{mode_1} و {mode_2}یش دۆخی تاریک چالاک دەکەن}
=3    {{mode_1}، {mode_2}، و {mode_3}یش دۆخی تاریک چالاک دەکەن}
other {{mode_1}، {mode_2}، و #ـی تریش دۆخی تاریک چالاک دەکەن}
}

{numberOfCertificates, plural,
        =1 {ڕێکخراوی {orgName} بڕوانامەیەکی سەرپەرشتیاری لەسەر ئامێرەکەت دامەزراندووە، کە ڕەنگە ڕێگەیان پێبدات چاودێریی چالاکیی تۆڕی ئامێرەکەت بکەن، بە ئیمەیڵەکان، بەرنامەکان و ماڵپەڕە پارێزراوەکانیشەوە.

بۆ زانیاریی زیاتر دەربارەی ئەم بڕوانامەیە، پەیوەندی بە سەرپەرشتیارەکەتەوە بکە.}
        other {ڕێکخراوی {orgName} چەند بڕوانامەیەکی سەرپەرشتیاری لەسەر ئامێرەکەت دامەزراندووە، کە ڕەنگە ڕێگەیان پێبدات چاودێریی چالاکیی تۆڕی ئامێرەکەت بکەن، بە ئیمەیڵەکان، بەرنامەکان و ماڵپەڕە پارێزراوەکانیشەوە.

بۆ زانیاریی زیاتر دەربارەی ئەم بڕوانامانە، پەیوەندی بە سەرپەرشتیارەکەتەوە بکە.}
        }

{numberOfCertificates, plural,
        =1 {ڕێکخراوی {orgName} بڕوانامەیەکی سەرپەرشتیاری بۆ پڕۆفایلی کارەکەت دامەزراندووە، کە ڕەنگە ڕێگەیان پێبدات چاودێریی چالاکیی تۆڕی کار بکەن، بە ئیمەیڵەکان، بەرنامەکان و ماڵپەڕە پارێزراوەکانیشەوە.

بۆ زانیاریی زیاتر دەربارەی ئەم بڕوانامەیە، پەیوەندی بە سەرپەرشتیارەکەتەوە بکە.}
        other {ڕێکخراوی {orgName} چەند بڕوانامەیەکی سەرپەرشتیاری بۆ پڕۆفایلی کارەکەت دامەزراندووە، کە ڕەنگە ڕێگەیان پێبدات چاودێریی چالاکیی تۆڕی کار بکەن، بە ئیمەیڵەکان... بەرنامەکان و ماڵپەڕە پارێزراوەکانیشەوە.

بۆ زانیاریی زیاتر دەربارەی ئەم بڕوانامانە، پەیوەندی بە سەرپەرشتیارەکەتەوە بکە.}
        }

